starterProgram:
{
  "format": "plclab-lad",
  "version": 2,
  "name": "Main",
  "variables": [
    {
      "name": "StartPB",
      "type": "BOOL",
      "direction": "input",
      "comment": "Start button S1, normally open: TRUE while pressed."
    },
    {
      "name": "StopPB",
      "type": "BOOL",
      "direction": "input",
      "comment": "Stop button S2, normally closed: TRUE while NOT pressed (wire-break safe)."
    },
    {
      "name": "MotorFeedback",
      "type": "BOOL",
      "direction": "input",
      "comment": "Contactor auxiliary contact: TRUE when the contactor has pulled in."
    },
    {
      "name": "OverloadOK",
      "type": "BOOL",
      "direction": "input",
      "comment": "Overload relay contact, normally closed: TRUE while the motor is not overloaded."
    },
    {
      "name": "MotorContactor",
      "type": "BOOL",
      "direction": "output",
      "comment": "Contactor coil K1: TRUE energizes the motor."
    },
    {
      "name": "RunLamp",
      "type": "BOOL",
      "direction": "output",
      "comment": "Green run lamp H1."
    }
  ],
  "rungs": [
    {
      "id": 1,
      "comment": "Start energizes the contactor. Add the self-holding branch, Stop and the overload contact.",
      "network": {
        "type": "series",
        "id": 2,
        "items": [
          {
            "type": "contact",
            "id": 3,
            "contact": "normallyOpen",
            "variable": "StartPB"
          }
        ]
      },
      "coils": [
        {
          "id": 4,
          "variable": "MotorContactor"
        }
      ]
    }
  ]
}
